export default async function(self, env, ctx) {
  const nums = [3, 1, 4, 1, 5];
  const odds = nums.filter(function (n) {
    return n % 2 === 1;
  });
  odds.sort(function (a, b) {
    return a - b;
  });
  return odds.reduce(function (sum, n) {
    return sum + n;
  }, 0);
}

