export default async function(self: Self, env: Env, ctx: Context): Promise<number> {
  const values = [3, 1, 4, 1, 5];
  const oddSorted = values.filter((value) => value % 2 !== 0).sort((a, b) => a - b);
  const sum = oddSorted.reduce((total, value) => total + value, 0);
  return sum;
}

