export default async function(self, env, ctx) {
  const tickets = await env.TICKETS.list();
  const ids = tickets
    .filter(function(ticket) {
      return ticket.priority === "high";
    })
    .map(function(ticket) {
      return ticket.id;
    })
    .sort(function(a, b) {
      if (a < b) return -1;
      if (a > b) return 1;
      return 0;
    });
  await self.report(ids);
}

