function sortStrings(xs: string[]) -> string[] {
  let n = 0;
  for (let _x in xs) {
    n = n + 1;
  }

  let i = 0;
  while (i < n) {
    let j = i + 1;
    while (j < n) {
      if (xs[j] < xs[i]) {
        let tmp = xs[i];
        xs[i] = xs[j];
        xs[j] = tmp;
      }
      j = j + 1;
    }
    i = i + 1;
  }

  xs
}

function Main(
  list: () -> QueryResult,
  get: (string) -> Ticket?,
  close: (CloseInput) -> Ok,
  flaky: () -> (Success | Failure),
  read: () -> int,
  write: (int) -> void,
  increment: () -> void,
  query: (QueryInput) -> QueryResult
) -> string[] {
  let result = list();
  let ids = [];

  for (let ticket in result.items) {
    if (ticket.priority == "high") {
      ids.push(ticket.id);
    }
  }

  sortStrings(ids)
}

