export default async function(self, env, ctx) {
  const tickets = await env.TICKETS.list();
  const result = tickets
    .filter(function (ticket) {
      return ticket.priority === "high";
    })
    .map(function (ticket) {
      return ticket.id;
    })
    .sort();
  await self.report(result);
  return result;
}
